head.script:
// 화면 리사이징

scwin.pSndNo;
scwin.pMktCd;
scwin.pSndlocCd;
scwin.gLdMktTp = js_market;
scwin.gDate;
scwin.gSndloc = js_sndloc; // 송신처구분코드

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        // 패널라운드 처리
        $c.cm.PanelToGroupBox(panel_1);
        pnl_type.hide();
        if (scwin.gLdMktTp === '1' || scwin.gLdMktTp === '2') {
            rdo_MktTpCd.setValue(scwin.gLdMktTp);
            rdo_SndLocTpCd.setValue(scwin.gSndloc);
            $c.cm.setColumnProp(grd_Grid, "LD_MKT_TP_NM", "show", false);
            $c.cm.setColumnProp(grd_Grid, "SNDLOC_TP_NM", "show", false);
        } else {
            pnl_type.show("");
            rdo_MktTpCd.setValue('9');
            rdo_SndLocTpCd.setValue('AA');
            $c.cm.setColumnProp(grd_Grid, "LD_MKT_TP_NM", "show", true);
            $c.cm.setColumnProp(grd_Grid, "SNDLOC_TP_NM", "show", true);
        }
        scwin.setCode();
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35006.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name grd_Grid_OnClick
 * @description grd_Grid 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnClick = async function(row, colid) {
    try {
        // 클릭된 값 변수에 셋팅
        scwin.setContnId(row);
        if (row >= 1) {
            const options = {
                id: "ULDSTF35006_POP",
                title: "보낸곳 목록",
                type: "browserPopup",
                width: "630px",
                height: "240px",
                callbackFn: "scwin.popupCallback"
            };

            $c.win.openPopup("/dscltrend/ULDSTF35006_POP.gfm", options);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35006.grd_Grid_OnClick" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35006.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        $c.stf.doLogSave('ULDSTF35006.xml', SCREN_PROCS_TP_CD_07);

        // var file_name = "통보내역";
        // var today = cGetToday('yyyymmddhhmmss');
        // var xls_path = getExcelDownPath()+today+"_"+file_name+".xlsx";
        $c.data.downloadGridViewExcel(grd_Grid, {fileName: "통보내역", type: "8"});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35006.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name img_FromCal_onclick
 * @description img_FromCal 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_FromCal_onclick = function() {
    try {
        popUpCalendar4(edt_SDate, 1);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35006.img_FromCal_onclick" });
    }
};

/**
 * @method
 * @name img_ToCal_onclick
 * @description img_ToCal 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_ToCal_onclick = function() {
    try {
        popUpCalendar4(edt_EDate, 2);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35006.img_ToCal_onclick" });
    }
};

/**
 * @method
 * @name edt_SDate_OnLastChar
 * @description edt SDate On Last Char 처리
 * @param {*} ch ch
 * @returns {void}
 * @hidden N
 */
scwin.edt_SDate_OnLastChar = function(ch) {
    try {
        afterPopUpCalendar(1); // if(시작일>종료일) 종료일=시작일;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35006.edt_SDate_OnLastChar" });
    }
};

/**
 * @method
 * @name edt_EDate_OnLastChar
 * @description edt EDate On Last Char 처리
 * @param {*} ch ch
 * @returns {void}
 * @hidden N
 */
scwin.edt_EDate_OnLastChar = function(ch) {
    try {
        afterPopUpCalendar(2); // if(시작일>종료일) 시작일=종료일;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35006.edt_EDate_OnLastChar" });
    }
};

/**
 * @method
 * @name cmb_PeriodTp_onselchange
 * @description cmb_PeriodTp onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_PeriodTp_onselchange = function() {
    try {
        const vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
        $c.stf.setFromToDate(vTp, edt_SDate, edt_EDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35006.cmb_PeriodTp_onselchange" });
    }
};

/**
 * @method
 * @name dts_list_OnLoadCompleted
 * @description dts_list 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_list_OnLoadCompleted = async function(rowcount) {
    try {
        if (dts_list.errorMsg) {
            await $c.win.alert("조회할 수 없습니다. 시스템 관리자에게 문의하세요");
        } else {
            txb_TotalCnt.setValue("총건수 : " + rowcount);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35006.dts_list_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_list_OnLoadError
 * @description dts_list 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_list_OnLoadError = async function() {
    try {
        await $c.win.alert("조회할 수 없습니다. 시스템 관리자에게 문의하세요");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35006.dts_list_OnLoadError" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    if (!await scwin.validCheck()) return;
    txb_TotalCnt.setValue("총건수 : ");

    // 그리드의 데이타 조회
    const sbmOptions = {
        id : "sbm_dts_list",
        action : "/AtsContactInfo.do",
        ref : "",
        target : "dts_list=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setCode
 * @description 기간 from~ to  셋팅
 * @returns {void}
 * @hidden N
 */
scwin.setCode = function() {
    //  기간 from~ to  셋팅
    edt_SDate.setValue($c.ut.cGetToday("yyyymmdd"));
    edt_EDate.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜

    $c.stf.comboCbDataSetPeriod(cmb_PeriodTp);
};

/**
 * @method
 * @name validCheck
 * @description 일자자 체크
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.validCheck = async function() {
    // 일자자 체크
    if (edt_SDate.getValue().length < 8) {
        await $c.win.alert("일자를 올바르게 입력하십시오.");
        edt_SDate.focus();
        return false;
    }

    // 일자 체크
    if (edt_EDate.getValue().length < 8) {
        await $c.win.alert("일자를 올바르게 입력하십시오.");
        edt_EDate.focus();
        return false;
    }
    if ($c.stf.compareFromToDate2(edt_SDate, edt_EDate) === false) {
        return false;
    }
    return true;
};

/**
 * @method
 * @name setContnId
 * @description 그리드에서 클릭 row의 변수셋팅
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setContnId = function(obj) {
    scwin.pSndNo = dts_list.getCellData(Number(obj), "SND_NO");
    scwin.pMktCd = dts_list.getCellData(Number(obj), "LD_MKT_TP_CD");
    scwin.pSndlocCd = dts_list.getCellData(Number(obj), "SNDLOC_TP_CD");
};
